import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.toList;class Result {public static String gamingArray(List<Integer> arr) {int moves = 0;int currentMax = -1;for (int num : arr) {if (num > currentMax) {currentMax = num;moves++;}}return (moves % 2 != 0) ? "BOB" : "ANDY";}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(System.out));String gStr = bufferedReader.readLine();if (gStr != null) {int g = Integer.parseInt(gStr.trim());for (int i = 0; i < g; i++) {int arrCount = Integer.parseInt(bufferedReader.readLine().trim());List<Integer> arr = Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(toList());String result = Result.gamingArray(arr);bufferedWriter.write(result);bufferedWriter.newLine();}}bufferedReader.close();bufferedWriter.close();}}